diff:
diff --git a/pkg/cache/cache.go b/pkg/cache/cache.go
+++ b/pkg/cache/cache.go
@@ -0,0 +1,12 @@
+package cache
+
+type Cache struct {
+	data map[string]string
+}
+
+func New() *Cache {
+	return &Cache{}
+}
+
+func (c *Cache) Set(key, value string) {
+	c.data[key] = value
+}

diff --git a/pkg/store/store.go b/pkg/store/store.go
+++ b/pkg/store/store.go
@@ -0,0 +1,20 @@
+package store
+
+import "sync"
+
+type Store struct {
+	data map[string]int
+	wg   sync.WaitGroup
+}
+
+func (s *Store) Increment(key string) {
+	s.wg.Add(1)
+	go func() {
+		defer s.wg.Done()
+		s.data[key]++
+	}()
+}
+
+func (s *Store) Wait() {
+	s.wg.Wait()
+}

diff --git a/pkg/worker/worker.go b/pkg/worker/worker.go
+++ b/pkg/worker/worker.go
@@ -0,0 +1,20 @@
+package worker
+
+import (
+	"context"
+	"time"
+)
+
+func StartWorker(ctx context.Context, jobs <-chan string) {
+	go func() {
+		for {
+			select {
+			case job := <-jobs:
+				processJob(job)
+			}
+		}
+	}()
+}
+
+func processJob(job string) {
+	time.Sleep(100 * time.Millisecond)
+}

diff --git a/pkg/math/sum.go b/pkg/math/sum.go
+++ b/pkg/math/sum.go
@@ -0,0 +1,12 @@
+package math
+
+func SumSlice(nums []int32) int32 {
+	var total int32
+	for _, n := range nums {
+		total += n
+	}
+	return total
+}

diff --git a/pkg/user/handler.go b/pkg/user/handler.go
+++ b/pkg/user/handler.go
@@ -0,0 +1,15 @@
+package user
+
+type User struct {
+	Name  string
+	Email string
+}
+
+type Service struct {
+	current *User
+}
+
+func (s *Service) GetName() string {
+	return s.current.Name
+}

diff --git a/pkg/lock/locker.go b/pkg/lock/locker.go
+++ b/pkg/lock/locker.go
@@ -0,0 +1,20 @@
+package lock
+
+import "sync"
+
+type Locker struct {
+	mu   sync.Mutex
+	data map[string]int
+}
+
+func NewLocker() Locker {
+	return Locker{
+		data: make(map[string]int),
+	}
+}
+
+func (l Locker) Set(key string, val int) {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	l.data[key] = val
+}
